<?php

declare(strict_types=1);

namespace EventMenu\Services;

use EventMenu\Core\Database;
use EventMenu\Core\TenantFeatures;
use PDO;
use RuntimeException;

final class PublicMenuService
{
    public function create(int$tenantId,array$cart,string$customerName,string$phone,string$address,?string$tableToken=null,string$fulfillment='delivery',?int$eventId=null):array
    {
        $customerName=mb_substr(trim($customerName),0,160);$phone=mb_substr(trim($phone),0,30);$address=mb_substr(trim($address),0,1000);$tableToken=trim((string)$tableToken);$fulfillment=strtolower(trim($fulfillment));$eventId=$eventId&&$eventId>0?$eventId:null;if($customerName==='')throw new RuntimeException('Nome é obrigatório.');$rows=[];foreach($cart as$row){if(!is_array($row))continue;$id=(int)($row['product_id']??0);$qty=(float)($row['qty']??$row['quantity']??0);if($id<1||!is_finite($qty)||$qty<=0)continue;$row['product_id']=$id;$row['qty']=$qty;$rows[]=$row;}if(!$rows)throw new RuntimeException('Carrinho vazio.');
        return Database::transaction(function(PDO$tx)use($tenantId,$rows,$customerName,$phone,$address,$tableToken,$fulfillment,$eventId):array{
            $tenantStmt=$tx->prepare(Database::portableSql($tx,'SELECT * FROM tenants WHERE id=? AND status="active" FOR UPDATE'));$tenantStmt->execute([$tenantId]);$tenant=$tenantStmt->fetch();if(!$tenant||!TenantFeatures::menu($tenantId))throw new RuntimeException('Cardápio indisponível.');$settings=json_decode((string)($tenant['settings']??'{}'),true)?:[];$tableId=null;$tabId=null;$unitId=null;$channel='delivery';$orderEventId=null;$publicUnits=new PublicUnitService();
            if($tableToken!==''&&$eventId)throw new RuntimeException('Pedido de evento não pode ser vinculado a uma mesa.');
            if($tableToken!==''){$lock=$tx->prepare(Database::portableSql($tx,'SELECT * FROM restaurant_tables WHERE tenant_id=? AND qr_token=? AND status<>"inactive" FOR UPDATE'));$lock->execute([$tenantId,$tableToken]);$table=$lock->fetch();if(!$table)throw new RuntimeException('Mesa não está disponível.');$tableId=(int)$table['id'];$unitId=isset($table['unit_id'])&&$table['unit_id']!==null?(int)$table['unit_id']:null;if(!$unitId)throw new RuntimeException('Esta mesa ainda não está vinculada a uma unidade operacional.');$unit=$tx->prepare('SELECT id FROM operating_units WHERE id=? AND tenant_id=? AND active=1 LIMIT 1');$unit->execute([$unitId,$tenantId]);if(!$unit->fetchColumn())throw new RuntimeException('A unidade desta mesa está inativa. Fale com a equipe.');$publicUnits->selectById($tenantId,$unitId);$channel='table';$tab=$tx->prepare(Database::portableSql($tx,'SELECT id FROM tabs WHERE tenant_id=? AND table_id=? AND status="open" ORDER BY id DESC LIMIT 1 FOR UPDATE'));$tab->execute([$tenantId,$tableId]);$tabId=$tab->fetchColumn();if($tabId===false){$tx->prepare('INSERT INTO tabs (tenant_id,table_id,label,status) VALUES (?, ?, ?, "open")')->execute([$tenantId,$tableId,'QR '.$table['name']]);$tabId=(int)$tx->lastInsertId();}}
            elseif($eventId){$eventStmt=$tx->prepare(Database::portableSql($tx,'SELECT id,name,status,bar_enabled,bar_unit_id FROM events WHERE id=? AND tenant_id=? FOR UPDATE'));$eventStmt->execute([$eventId,$tenantId]);$event=$eventStmt->fetch();if(!$event||(string)$event['status']!=='published')throw new RuntimeException('Este evento não está disponível para pedidos.');if(!(int)$event['bar_enabled'])throw new RuntimeException('O cardápio do bar está desativado para este evento.');$barUnitId=(int)($event['bar_unit_id']??0);if($barUnitId<1)throw new RuntimeException('O bar deste evento ainda não possui uma unidade de atendimento configurada.');$selectedUnit=$publicUnits->selectById($tenantId,$barUnitId);$unitId=(int)$selectedUnit['id'];$channel='event_bar';$orderEventId=$eventId;if($phone==='')throw new RuntimeException('Telefone é obrigatório para acompanhar o pedido do evento.');}
