            $configured=new ConfiguredOrderService();$items=[];$subtotal=0;foreach($rows as$row){$resolved=$configured->resolveLine($tx,$tenantId,$row,true);$subtotal+=(int)$resolved['total_cents'];$items[]=$resolved;}$deliveryFee=$channel==='delivery'?max(0,(int)($settings['delivery_fee_cents']??0)):0;$minimum=max(0,(int)($settings['min_delivery_order_cents']??0));if($channel==='delivery'&&$subtotal<$minimum)throw new RuntimeException('Pedido mínimo para delivery: R$ '.number_format($minimum/100,2,',','.').'.');$total=$subtotal+$deliveryFee;if($total<=0)throw new RuntimeException('Pedido sem valor válido.');
            $customerId=null;if($phone!==''){$c=$tx->prepare('SELECT id FROM customers WHERE tenant_id=? AND phone=? ORDER BY id DESC LIMIT 1');$c->execute([$tenantId,$phone]);$customerId=$c->fetchColumn()?:null;}if($customerId){$tx->prepare('UPDATE customers SET name=? WHERE id=? AND tenant_id=?')->execute([$customerName,$customerId,$tenantId]);}else{$c=$tx->prepare('INSERT INTO customers (tenant_id,name,phone) VALUES (?,?,?)');$c->execute([$tenantId,$customerName,$phone?:null]);$customerId=(int)$tx->lastInsertId();}
            $publicToken=bin2hex(random_bytes(20));$s=$tx->prepare('INSERT INTO orders (public_token,tenant_id,unit_id,event_id,customer_id,table_id,tab_id,channel,status,payment_status,subtotal_cents,delivery_fee_cents,total_cents,delivery_address) VALUES (?,?,?,?,?,?,?,?,"pending","unpaid",?,?,?,?)');$s->execute([$publicToken,$tenantId,$unitId,$orderEventId,$customerId,$tableId,$tabId,$channel,$subtotal,$deliveryFee,$total,$channel==='delivery'?$address:null]);$orderId=(int)$tx->lastInsertId();$ins=$tx->prepare('INSERT INTO order_items (order_id,product_id,name_snapshot,unit_price_cents,quantity,total_cents) VALUES (?,?,?,?,?,?)');foreach($items as$item){$ins->execute([$orderId,$item['product_id'],$item['name'],$item['unit_price_cents'],$item['quantity'],$item['total_cents']]);$configured->persistModifiers($tx,$tenantId,$orderId,(int)$tx->lastInsertId(),$item);}if($tableId)$tx->prepare('UPDATE restaurant_tables SET status=CASE WHEN status="available" THEN "occupied" ELSE status END WHERE id=? AND tenant_id=? AND unit_id=?')->execute([$tableId,$tenantId,$unitId]);$expires=(new\DateTimeImmutable('+30 minutes'))->format('Y-m-d H:i:s');(new StockReservationService())->reserve($tx,$tenantId,$orderId,$items,$expires);$isEventBar=$channel==='event_bar';$history=$isEventBar?'Pedido criado pelo cardápio do evento.':($channel==='pickup'?'Pedido de retirada criado pelo cardápio digital.':'Pedido criado pelo cardápio digital.');(new OrderHistoryService())->record($tx,$tenantId,$orderId,null,'pending',$isEventBar?'event_public':'public',$history,null);return['id'=>$orderId,'public_token'=>$publicToken,'subtotal_cents'=>$subtotal,'delivery_fee_cents'=>$deliveryFee,'total_cents'=>$total,'channel'=>$channel,'unit_id'=>$unitId,'event_id'=>$orderEventId,'table_id'=>$tableId,'tab_id'=>$tabId,'stock_reserved_until'=>$expires];
        });
    }
}
